KBAT.guet.d='On voit venir de loin : sur deux cases autour, les rencontres avec les chasseurs de marrons sont bien plus rares, et le camp a le temps de fuir.';
// choisir un roi
function roiChoix97(){const o=$('roi97');if(o)o.remove();const d=document.createElement('div');d.id='roi97';d.style.cssText='position:fixed;inset:0;z-index:9900;background:#000a;display:flex;align-items:center;justify-content:center';
 d.innerHTML='<div class="pjb" style="max-width:560px;background:#1a140c;color:#f4ead6;border:1px solid #e8be5a;border-radius:12px;padding:16px"><h2 style="margin:0 0 6px">Choisir un roi</h2><p class="note">Sans roi, on est plus libre : chacun fait aussi ce qu’il veut, on découvre et on apprend plus vite ; mais on produit un peu moins et les disputes éclatent plus souvent. Un roi décide selon ce qu’il est.</p>'+
 Object.entries(ROIS97).map(([k,R])=>'<button class="bt sec" data-roi97="'+k+'" style="display:block;width:100%;text-align:left;margin:6px 0;padding:8px 10px"><b>'+R.n+'</b><br><small>'+R.d+'</small></button>').join('')+'<small style="opacity:.75">Noms venus de la tradition orale ; les atouts sont une interprétation du jeu.</small><div style="margin-top:8px"><button class="bt sec" id="roi97x">Plus tard</button></div></div>';
 document.body.appendChild(d);d.querySelectorAll('[data-roi97]').forEach(b=>b.onclick=()=>{K.roi97=b.dataset.roi97;kLog('Le camp se donne un roi : '+ROIS97[K.roi97].n+'.');d.remove();try{kPanneau();kRendu()}catch(_){}});$('roi97x').onclick=()=>d.remove()}
