// ----- 21. Jamais bloqué par un choix : toucher à côté de la fenêtre passe, ou laisse le jeu choisir -----
{const EXCL=/^(kons|campV|vp|bt|m2|hb|rallye|cine|c|ecran|jeu)$/;
 const auto=box=>{const B=[...box.querySelectorAll('button')].filter(b=>!b.disabled&&b.offsetParent);if(!B.length)return false;
  const pref=B.find(b=>b.classList.contains('conte'))||B.find(b=>/^(passer|plus tard|fermer|continuer|laisser faire|le faire pour moi|ok|compris|suivant)/i.test(b.textContent.trim()))||B.find(b=>/annuler|retour|✕|×/i.test(b.textContent))||(box.id==='modal'?box.querySelector('.op:not([disabled])'):null)||B[0];
  if(pref){pref.click();return true}return false};
 addEventListener('click',e=>{try{const t=e.target;if(!t||t.nodeType!==1||EXCL.test(t.id||''))return;const cs=getComputedStyle(t);if(cs.position!=='fixed')return;const r=t.getBoundingClientRect();if(r.width<innerWidth*.9||r.height<innerHeight*.9)return;
  const m=/rgba?\(([^)]+)\)/.exec(cs.backgroundColor);const al=m?(m[1].split(',')[3]!=null?parseFloat(m[1].split(',')[3]):1):0;if(al<.15||al>.97)return;
  // le clic tombe sur le fond, pas sur la fenêtre
  const box=[...t.children].find(c=>{const q=c.getBoundingClientRect();return q.width<innerWidth*.98&&q.height>40});if(!box)return;const q=box.getBoundingClientRect();if(e.clientX>=q.left&&e.clientX<=q.right&&e.clientY>=q.top&&e.clientY<=q.bottom)return;
  if(auto(t)){e.stopPropagation();e.preventDefault();try{toast('Le jeu a choisi pour vous.')}catch(_){}}}catch(_){}},true)}

